//! `ironclaw routines` — manage scheduled routines from the CLI.//!//! Provides subcommands for listing, creating, editing, enabling/disabling,//! deleting, and viewing run history of routines without starting the full agent.use std::sync::Arc;use chrono::{DateTime, Utc};use clap::Subcommand;use uuid::Uuid;use crate::agent::routine::{    NotifyConfig, Routine, RoutineAction, RoutineGuardrails, Trigger, next_cron_fire,};use crate::db::Database;/// Routines subcommands.#[derive(Subcommand, Debug, Clone)]pub enum RoutinesCommand {    /// List routines    List {        /// Filter by trigger type (e.g. "cron", "webhook", "event")        #[arg(long)]        trigger: Option<String>,        /// Include disabled routines        #[arg(long)]        disabled: bool,        /// Output as JSON (for scripting)        #[arg(long)]        json: bool,    },    /// Create a new cron routine    #[command(alias = "add")]    Create {        /// Routine name (must be unique per user)        #[arg(long)]        name: String,        /// Cron schedule (6-field: "sec min hour day month weekday")        #[arg(long)]        schedule: String,        /// Prompt for the LLM        #[arg(long)]        prompt: String,        /// Optional description        #[arg(long, default_value = "")]        description: String,        /// IANA timezone (e.g. "America/New_York")        #[arg(long)]        timezone: Option<String>,        /// Cooldown between fires in seconds        #[arg(long, default_value = "300")]        cooldown: u64,        /// Notification channel        #[arg(long)]        notify_channel: Option<String>,    },    /// Edit an existing routine    #[command(alias = "update")]    Edit {        /// Routine name        #[arg(long)]        name: String,        /// New schedule        #[arg(long)]        schedule: Option<String>,        /// New prompt        #[arg(long)]        prompt: Option<String>,        /// New description        #[arg(long)]        description: Option<String>,        /// New timezone        #[arg(long)]        timezone: Option<String>,        /// New cooldown in seconds        #[arg(long)]        cooldown: Option<u64>,    },    /// Enable a routine    Enable {        /// Routine name        name: String,    },    /// Disable a routine    Disable {        /// Routine name        name: String,    },    /// Delete a routine    #[command(alias = "rm")]    Delete {        /// Routine name        name: String,        /// Skip confirmation prompt        #[arg(short, long)]        yes: bool,    },    /// Show run history for a routine    #[command(alias = "runs")]    History {        /// Routine name        name: String,        /// Maximum number of runs to show        #[arg(short, long, default_value = "10")]        limit: i64,        /// Output as JSON (for scripting)        #[arg(long)]        json: bool,    },}/// Run a routines CLI command against the database.